using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using DomainConsole.Shared;
namespace DomainConsole;
public sealed class BitsObservation {public long Bytes {get;set;}public DateTimeOffset Seen {get;set;}public DateTimeOffset Changed {get;set;}public DateTimeOffset ContinuousSince {get;set;}public int Samples {get;set;}public double Speed {get;set;}}
public sealed class DownloadSettings {public bool AutomaticRecovery {get;set;}public int NoMovementMinutes {get;set;}=30;}
public partial class MainWindow {
 readonly Dictionary<string,BitsObservation> bitsObservations=Store.Read("bits-observations.json",new Dictionary<string,BitsObservation>());
 readonly Dictionary<string,DateTimeOffset> recoveryAttempts=Store.Read("download-recovery-attempts.json",new Dictionary<string,DateTimeOffset>());
 void ObserveBits(string host,BackgroundDownload download,DateTimeOffset now){var key=host+"|"+download.Id;if(!bitsObservations.TryGetValue(key,out var value))bitsObservations[key]=value=new(){Bytes=download.Received,Changed=now,Seen=now,ContinuousSince=now};bool gap=now-value.Seen>TimeSpan.FromSeconds(90);if(gap){value.ContinuousSince=now;value.Samples=0;value.Changed=now;}value.Speed=gap?0:Math.Max(0,download.Received-value.Bytes)/Math.Max(1,(now-value.Seen).TotalSeconds);if(download.Received!=value.Bytes)value.Changed=now;value.Bytes=download.Received;value.Seen=now;value.Samples++;}
 public static bool RecoveryEligible(LiveUpdateActivity live,RemoteState? state,BitsObservation observation,int minutes,DateTimeOffset now)=>!live.InstallerBusy&&live.InstallationEvidence.Length==0&&live.Limitation.Length==0&&FreshActivity(live)&&observation.Samples>=3&&now-observation.Seen<TimeSpan.FromSeconds(45)&&now-observation.ContinuousSince>=TimeSpan.FromMinutes(minutes)&&now-observation.Changed>=TimeSpan.FromMinutes(minutes)&&live.Downloads.Any(d=>d.State is "Queued" or "Transferring")&&(state==null?live.InstallationEvidence.Length==0:state.Status=="Running"&&state.Stage.Contains("Скачивание")&&DateTimeOffset.TryParse(state.Updated,out var updated)&&now-updated<TimeSpan.FromSeconds(90));
 async Task MaybeRecoverDownload(ComputerRow row,LiveUpdateActivity live){var settings=Store.Read("download-settings.json",new DownloadSettings());if(!settings.AutomaticRecovery||closing||!ConnectionFresh(row.Host))return;if(recoveryAttempts.ContainsKey(row.Host))return;var state=ExecutionRow(row,true).Target.State;var eligible=live.Downloads.Any(d=>bitsObservations.TryGetValue(row.Host+"|"+d.Id,out var observation)&&RecoveryEligible(live,state,observation,settings.NoMovementMinutes,DateTimeOffset.UtcNow));if(!eligible)return;recoveryAttempts[row.Host]=DateTimeOffset.UtcNow;Store.Write("download-recovery-attempts.json",recoveryAttempts);var script="if((New-Object -ComObject Microsoft.Update.Installer).IsBusy){throw 'Началась установка; автовосстановление отменено'};"+RestartServicesScript(new[]{"bits","UsoSvc","wuauserv"},false);var job=new RemoteJob{Name="Автовосстановление загрузки · однократная попытка",OutputChannel="Commands",AllowUpdateConflict=true,Steps=new(){new(){Name="Перезапуск служб загрузки",Kind="PowerShell",Code=script}}};var target=Store.Clone(row.Target);target.State=null;target.Output="";target.Status="Queued";job.Targets.Add(target);History.Insert(0,job);queue.Enqueue((job,target));Save();Notify(row.Name+": автоматическая попытка восстановления загрузки; кэш сохранён. Итог в истории.");await SendQueue();}
 void SaveDownloadSettings_Click(object sender,RoutedEventArgs e)=>Guard(()=>{if(!int.TryParse(DownloadWaitBox.Text,out var minutes)||minutes<10||minutes>180)throw new Exception("Порог: 10–180 минут.");Store.Write("download-settings.json",new DownloadSettings{AutomaticRecovery=AutomaticDownloadRecovery.IsChecked==true,NoMovementMinutes=minutes});Notify("Настройки сохранены. Не более одной автоматической попытки на ПК; счётчик можно сбросить отдельно.");});
 void ResetRecoveryAttempts_Click(object sender,RoutedEventArgs e){recoveryAttempts.Clear();Store.Write("download-recovery-attempts.json",recoveryAttempts);Notify("Счётчики автоматических попыток сброшены.");}
 public static string PriorityScript(string id,bool restore){if(!Guid.TryParse(id,out _))throw new ArgumentException("Неверный ID BITS");return "$ErrorActionPreference='Stop';$id=[guid]"+PowerShellBridge.Literal(id)+";$j=Get-BitsTransfer -AllUsers|Where-Object {$_.JobId -eq $id -and $_.DisplayName -eq 'WU Client Download' -and $_.OwnerAccount -match '(?i)(SYSTEM|СИСТЕМА)$'};if(!$j){throw 'Задание Windows Update уже отсутствует; обновите снимок'};$root=Join-Path $env:ProgramData 'DomainConsoleCSharp\\Controls';New-Item $root -ItemType Directory -Force|Out-Null;$path=Join-Path $root ('priority-'+$id+'.json');"+(restore?"if(!(Test-Path $path)){throw 'Исходный приоритет не сохранён'};$saved=Get-Content $path -Raw|ConvertFrom-Json;$j|Set-BitsTransfer -Priority $saved.Priority|Out-Null;Remove-Item $path -Force;'Исходный приоритет восстановлен: '+$saved.Priority":"if(!(Test-Path $path)){@{Id=[string]$id;Priority=[string]$j.Priority;ChangedUtc=[DateTime]::UtcNow.ToString('o')}|ConvertTo-Json|Set-Content $path -Encoding UTF8};$j|Set-BitsTransfer -Priority Foreground|Out-Null;'Ускоренный режим Foreground включён для выбранного задания. Ограничения сервера и сети сохраняются.'");}
 async void DownloadPriority_Click(object sender,RoutedEventArgs e)=>await Guard(async()=>{var row=Current();if(!backgroundUpdates.TryGetValue(row.Host,out var live)||!FreshActivity(live)){await RefreshBackground();live=backgroundUpdates.GetValueOrDefault(row.Host);};if(live==null||!FreshActivity(live)||live.Downloads.Count==0)throw new Exception("Нужен свежий снимок BITS выбранного компьютера.");var panel=new StackPanel{Margin=new(16)};var list=new ComboBox{ItemsSource=live.Downloads,DisplayMemberPath="Label",SelectedIndex=0,Margin=new(0,8,0,8)};panel.Children.Add(new TextBlock{Text="Выберите задание BITS. Foreground может занять доступную полосу, включая ограниченный 3G. Смена приоритета не меняет политику стоимости и не гарантирует ускорение.",TextWrapping=TextWrapping.Wrap});panel.Children.Add(list);bool restore=false;var w=new Window{Owner=this,Title="Скорость загрузки",Width=500,SizeToContent=SizeToContent.Height,Content=panel,WindowStartupLocation=WindowStartupLocation.CenterOwner};foreach(var choice in new[]{("Ускорить выбранное задание",false),("Вернуть исходный приоритет",true)}){var b=new Button{Content=choice.Item1,Margin=new(0,3,0,3)};b.Click+=(s,a)=>{restore=choice.Item2;w.DialogResult=true;};panel.Children.Add(b);}if(w.ShowDialog()!=true||list.SelectedItem is not BackgroundDownload download)return;MicrosoftBox.IsChecked=false;await Submit(new(){new(){Name=restore?"Возврат скорости BITS":"Ускорение BITS",Kind="PowerShell",Code=PriorityScript(download.Id,restore)}},"Commands",true);});
}
